create extension if not exists pgcrypto;
create table if not exists data_imports(id uuid primary key default gen_random_uuid(), file_name text not null, source_year int, imported_at timestamptz default now(), status text not null default 'validated', rows_count int default 0, anomalies_count int default 0, metadata jsonb default '{}'::jsonb);
create table if not exists agencies(id uuid primary key default gen_random_uuid(), code text unique not null, name text unique not null, active boolean default true);
create table if not exists client_types(id uuid primary key default gen_random_uuid(), code text unique not null, name text unique not null);
create table if not exists facturation_monthly(id uuid primary key default gen_random_uuid(), import_id uuid references data_imports(id), period_month date not null, agency_id uuid references agencies(id), client_type_id uuid references client_types(id), subscribers_forfait numeric, subscribers_mesure numeric, subscribers_total numeric, volume_consume_forfait numeric, volume_facture_forfait numeric, volume_consume_mesure numeric, volume_facture_mesure numeric, volume_consume_total numeric, volume_facture_total numeric, amount_forfait numeric, amount_mesure numeric, amount_total numeric, amount_penalty numeric, amount_paid numeric, balance_due numeric, recovery_rate numeric, source jsonb default '{}'::jsonb, unique(period_month,agency_id,client_type_id));
create table if not exists technique_monthly(id uuid primary key default gen_random_uuid(), import_id uuid references data_imports(id), period_month date not null, agency_id uuid references agencies(id), volume_produced numeric, volume_consumed numeric, volume_billed numeric, network_yield numeric, billing_ratio numeric, source jsonb default '{}'::jsonb, unique(period_month,agency_id));
create table if not exists recouvrement_monthly(id uuid primary key default gen_random_uuid(), import_id uuid references data_imports(id), period_month date not null, agency_id uuid references agencies(id), client_type_id uuid references client_types(id), amount_forfait numeric, amount_mesure numeric, amount_total numeric, amount_penalty numeric, amount_paid numeric, balance_due numeric, amount_paid_updated numeric, balance_due_updated numeric, recovery_rate numeric, recovery_rate_updated numeric, evolution numeric, source jsonb default '{}'::jsonb, unique(period_month,agency_id,client_type_id));
create table if not exists data_quality_issues(id uuid primary key default gen_random_uuid(), import_id uuid references data_imports(id), severity text not null, category text not null, message text not null, sheet_name text, excel_row int, created_at timestamptz default now(), resolved boolean default false);
insert into agencies(code,name) values ('YIM','Yimbaya'),('MAT','Matoto'),('KOU','Kountia'),('WAN','Wanindara'),('CIM','Cimenterie'),('RAT','Ratoma'),('DIX','Dixinn'),('KAL','Kaloum'),('MTA','Matam') on conflict do nothing;
